mapper.select:
SELECT COUNT(*) AS cnt FROM APPROVAL AS A LEFT JOIN REQUEST AS R ON A.rqidx = R.rqidx LEFT JOIN BOOKS AS B ON B.bidx = COALESCE(A.bidx, R.bidx) WHERE A.delyn = 'N' AND (B.delyn = 'N' OR B.delyn IS NULL) AND A.regyn = "N"
AND A.status = #{filter}
AND A.aidx != #{selectedAidx}

 SELECT COALESCE(A.bidx, R.bidx) AS bidx, B.coverImg, B.title, B.author, B.publisher, B.publishedYear, A.aidx
 FROM APPROVAL AS A
 LEFT JOIN REQUEST AS R ON A.rqidx = R.rqidx
 LEFT JOIN BOOKS AS B ON B.bidx = COALESCE(A.bidx, R.bidx)
 WHERE A.delyn = 'N' AND (B.delyn = 'N' OR B.delyn IS NULL) AND A.regyn = "N"


	AND A.status = #{filter}


    AND A.aidx != #{selectedAidx}

ORDER BY A.aidx LIMIT #{startPageNum}, #{perPageNum};
